escenas.animacion:
const W=A.W,H=A.H,ac=A.accent;
const tAsc=A.k('ascensores',0.33),tVal=A.k('Valparaíso',1.0),tSub=A.k('suben',1.33),tCer=A.k('cerros',2.0),tHace=A.k('hace',2.33),tCien=A.k('cien',3.33),tTru=A.k('truco',4.67);
A.bg('#0a1530','#050a18',true);
const x0=170,y0=1090,x1=880,y1=545;
const ang=Math.atan2(y1-y0,x1-x0);
const P=u=>[A.lerp(x0,x1,u),A.lerp(y0,y1,u)];
const hill=[[30,1120],[x0-40,y0+20],[x1,y1],[1050,y1-10],[1050,1120]];
const hp=A.p(0,0.9,'softLand');
const glowC=A.clamp(1-Math.abs(t-tCer-0.3)/0.6);
A.with(()=>{
  ctx.save();ctx.globalAlpha=hp;
  ctx.beginPath();hill.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath();
  const g=ctx.createLinearGradient(0,540,0,1120);g.addColorStop(0,'#16284f');g.addColorStop(1,'#0b1633');
  ctx.fillStyle=g;ctx.fill();ctx.restore();
  if(hp>0.3)A.lib.hatch(ctx,hill,{angle:45,spacing:20,width:1.4,color:'rgba(160,190,255,0.13)'});
},{});
A.line(hill.slice(0,4),{stroke:glowC>0?ac:'#e8f0ff',lw:4+glowC*3,progress:hp,glow:glowC*20});
// casas
const houses=[[520,1030],[650,965],[770,890],[900,830],[985,700],[700,1065],[850,1010],[985,920],[990,1060],[420,1075]];
houses.forEach((h,i)=>{
  const s=A.pop(tVal+i*0.07,0.45);if(s<=0)return;
  A.with(()=>{
    const [hx,hy]=h,w=72,hh=56;
    A.rect(hx-w/2,hy-hh,w,hh,{fill:'#0d1b3d',stroke:'#e8f0ff',lw:3});
    A.lib.inkPath(ctx,[[hx-w/2-6,hy-hh],[hx,hy-hh-30],[hx+w/2+6,hy-hh]],{width:3,color:'#e8f0ff',closed:true,fill:'#0d1b3d'});
    const on=A.clamp((t-tVal-i*0.07-0.2)/0.3);
    A.rect(hx-22,hy-hh+14,16,16,{fill:ac,alpha:0.25+0.75*on,glow:on*10});
    A.rect(hx+6,hy-hh+14,16,16,{fill:ac,alpha:0.25+0.75*on*((i%3)?1:0.3)});
  },{x:h[0],y:h[1],scale:s});
});
// rieles
const rp=A.p(0.2,0.9,'glide');
const nx=Math.sin(ang),ny=-Math.cos(ang);
A.line([[x0,y0],[x1,y1]],{stroke:'#c9d6f5',lw:5,progress:rp});
A.line([[x0-nx*14,y0-ny*14],[x1-nx*14,y1-ny*14]],{stroke:'#c9d6f5',lw:3,progress:rp,alpha:0.6});
for(let i=0;i<=14;i++){const u=i/14;if(u>rp)break;const [px,py]=P(u);A.line([[px+nx*8,py+ny*8],[px-nx*22,py-ny*22]],{stroke:'#c9d6f5',lw:3,alpha:0.5});}
// progreso del carro
const climb=A.p(tSub,Math.max(0.5,tTru-tSub-0.15),'glide');
const u=A.lerp(0.08,0.66,climb);
const [cx,cy]=P(u);
// estación + rueda
const wx=x1+30,wy=y1-60,wr=42;
const sp=A.p(0.4,0.6,'softLand');
const lit=A.p(tTru,0.35,'crashIn');
A.rect(x1-40,y1-120,150,120,{fill:'#0d1b3d',stroke:'#e8f0ff',lw:3,alpha:sp});
const cA=[cx+Math.cos(ang)*70-nx*40,cy+Math.sin(ang)*70-ny*40];
const cB=[wx-wr*0.6,wy+wr*0.8];
A.line([cA,cB],{stroke:lit>0?ac:'#ffffff',lw:3+lit*4,alpha:0.5+0.5*Math.max(lit,A.p(tSub-0.3,0.4)),glow:lit*24,progress:A.p(tAsc+0.2,0.7,'glide')});
const rot=u*20;
A.with(()=>{
  A.circle(wx,wy,wr,{stroke:lit>0?ac:'#e8f0ff',lw:5,fill:'#0a1530',glow:lit*20});
  for(let i=0;i<4;i++){const a=rot+i*Math.PI/4;A.line([[wx-Math.cos(a)*wr,wy-Math.sin(a)*wr],[wx+Math.cos(a)*wr,wy+Math.sin(a)*wr]],{stroke:lit>0?ac:'#e8f0ff',lw:3});}
  A.circle(wx,wy,7,{fill:ac});
},{alpha:sp});
if(t>tTru)A.rings(wx,wy,tTru,{count:3,speed:260,gap:0.25,maxR:200,color:ac,lw:4,alpha:0.8});
// carro
const cs=A.pop(tAsc,0.5);
if(cs>0){
  const bob=climb>0&&climb<1?Math.sin(t*18)*1.5:0;
  A.with(()=>{
    const bx=cx-80,by=cy-118+bob;
    A.rect(bx,by,160,104,{r:12,fill:ac,stroke:'#1a1200',lw:4,glow:14});
    A.lib.hatch(ctx,[[bx+110,by+8],[bx+156,by+8],[bx+156,by+100],[bx+110,by+100]],{angle:-45,spacing:9,width:1.5,color:'rgba(0,0,0,0.3)'});
    for(let i=0;i<3;i++)A.rect(bx+16+i*46,by+18,34,36,{r:5,fill:'#14223f'});
    A.rect(bx-6,by-10,172,14,{r:6,fill:'#e8f0ff'});
    A.circle(cx-45,cy-10+bob,12,{fill:'#0a1530',stroke:'#e8f0ff',lw:3});
    A.circle(cx+45,cy-10+bob,12,{fill:'#0a1530',stroke:'#e8f0ff',lw:3});
  },{x:cx,y:cy,rot:ang,scale:cs});
  if(climb>0.02&&climb<0.98)A.particles(6,7,(i,r)=>{const ph=((t*2+r())%1);const [px,py]=P(Math.max(0,u-0.05-ph*0.08));A.circle(px+nx*(r()*20-10),py+ny*(r()*20-10),3*(1-ph),{fill:'#e8f0ff',alpha:0.6*(1-ph)});});
}
// etiqueta CERRO (capa superior, zona libre bajo el riel, sobre las casas)
const cl=A.pop(tCer,0.45),clOut=1-A.p(tTru-0.2,0.35,'accelExit');
if(cl>0&&clOut>0){
  const lx=830,ly=1000;
  const gp=A.p(tCer+0.1,0.35,'glide');
  A.line([[lx-30,ly-42],[lx-80,ly-150]],{stroke:ac,lw:4,progress:gp,alpha:clOut});
  if(gp>0.95)A.circle(lx-80,ly-150,8,{fill:ac,alpha:clOut,glow:10});
  A.label('CERRO',lx,ly,{size:56,bg:ac,color:'#0a1530',scale:cl,alpha:clOut});
}
// contador +100 AÑOS (entra con "suben", cuenta con "hace más de cien años")
const tIn=tSub+0.15;
if(t>tIn){
  const cp=A.p(tHace,Math.max(0.6,tCien+0.35-tHace),'softInOut');
  const tLand=tCien+0.35;
  const dim=1-0.35*A.p(tTru,0.4,'softInOut');
  const land=A.clamp(1-(t-tLand)/0.3);
  const sh=(t>tLand&&t<tLand+0.3)?9*land:0;
  const bump=t>tLand?1+0.12*A.clamp(1-(t-tLand)/0.35):1;
  A.with(()=>{
    A.text('+'+A.counter(0,100,cp,0),540,1560,{size:250,color:ac,weight:900,align:'center',stroke:'#050a18',strokeWidth:10});
  },{x:540,y:1480,scale:A.pop(tIn,0.5)*bump,alpha:dim,shake:sh});
  A.with(()=>{
    A.text('AÑOS',540,1705,{size:98,color:'#ffffff',weight:800,align:'center',alpha:dim});
  },{x:540,y:1670,scale:A.pop(tIn+0.15,0.45)});
  if(t>tLand&&t<tLand+0.3)A.flash(tLand,0.25,0.25);
}
// ¿EL TRUCO? (desplazado a la izquierda, lejos del carro)
if(t>tTru){
  A.flash(tTru,0.25,0.3);
  const ls=A.pop(tTru+0.05,0.5);
  A.label('¿EL TRUCO?',310,640,{size:66,bg:ac,color:'#0a1530',scale:ls});
  const mx=(cA[0]+cB[0])/2,my=(cA[1]+cB[1])/2;
  A.arrow(430,600,mx-20,my+10,{progress:A.p(tTru+0.25,0.45,'glide'),color:ac,lw:6,head:22});
}

const W=A.W,H=A.H;
A.bg('#0B1A2E','#050C18',true);
const ACC=A.accent, INK='#0B1424', PALE=(A.pal&&A.pal.paleBlue)||'#BFD8FF';
const kAsc=A.k('ascensores',0.667), kEd=A.k('edificio:',1.333), kFun=A.k('funiculares.',2.0), kDos=A.k('Dos',2.333), kCar=A.k('carros',2.667);
const kRie=A.k('rieles,',3.333), kPen=A.k('pendiente,',4.333), kUni=A.k('unidos',4.667), kCab=A.k('cable.',6.0);
const C={x:540,y:850};
const slopeAng=Math.atan2(-560,720);
const pM=A.p(kFun-0.35,0.75,'whip');
const ang=A.lerp(-Math.PI/2,slopeAng,pM);
const L=A.lerp(260,400,pM);
const d={x:Math.cos(ang),y:Math.sin(ang)}; const n={x:d.y,y:-d.x};
const pt=(s,o)=>({x:C.x+d.x*s+n.x*o,y:C.y+d.y*s+n.y*o});
const P=(q)=>[q.x,q.y];
const OB=100; // riel de atrás
const Rw=50, sW=L+40, oW=A.lerp(0,62,pM);
const Wc=pt(sW,oW);
const wcar=180, hcar=130;
const m=A.p(kCab-0.45,1.0,'softInOut');
const MOV=50;
const sA=-0.55*400+m*MOV;   // carro 1 sube
const sB=0.35*400-m*MOV;    // carro 2 baja
const shake=t>kCab&&t<kCab+0.3?6*(1-(t-kCab)/0.3):0;

A.with(()=>{
  // ---- terreno / pendiente
  const pP=A.p(kPen-0.1,0.5,'softLand');
  if(pP>0){
    const g1=pt(-L-20,-8), g2=pt(sW+60,-8);
    const poly=[[g1.x,g1.y],[g2.x,g2.y],[g2.x,1120],[g1.x,1120]];
    ctx.save(); ctx.globalAlpha=pP;
    ctx.beginPath(); poly.forEach((q,i)=>i?ctx.lineTo(q[0],q[1]):ctx.moveTo(q[0],q[1])); ctx.closePath();
    ctx.fillStyle='#14263F'; ctx.fill();
    try{A.lib.hatch(ctx,poly,{angle:Math.PI/4,spacing:16,width:2,color:'rgba(191,216,255,0.18)'});}catch(e){}
    ctx.restore();
    A.line([P(g1),P(g2)],{stroke:'#BFD8FF',lw:4,alpha:pP*0.8});
    const b=pt(-L,0);
    const pa=A.p(kPen,0.6,'softLand');
    A.line([[b.x,b.y],[b.x+330,b.y]],{stroke:'#fff',lw:3,dash:[12,10],alpha:pa*0.8,progress:pa});
    ctx.save(); ctx.globalAlpha=pa; ctx.strokeStyle=ACC; ctx.lineWidth=6;
    ctx.beginPath(); ctx.arc(b.x,b.y,150,0,slopeAng*pa,true); ctx.stroke(); ctx.restore();
    const p38=A.p(kPen+0.2,0.4,'softLand');
    if(p38>0) A.with(()=>{A.text('38°',b.x+215,b.y-40,{size:52,color:'#fff',weight:800,align:'center'});},{x:b.x+215,y:b.y-40,scale:A.pop(kPen+0.2),alpha:p38});
  }

  // ---- paredes del hueco del edificio (se desvanecen)
  if(pM<1){
    const wa=1-pM;
    [-90,90].forEach(o=>{
      A.line([P(pt(-L,o)),P(pt(L+10,o))],{stroke:'#BFD8FF',lw:6,alpha:wa});
      for(let i=0;i<5;i++){const s=-L+i*130; A.line([P(pt(s,o)),P(pt(s,o+Math.sign(o)*40))],{stroke:'#BFD8FF',lw:3,alpha:wa*0.6});}
    });
  }

  // ---- rieles (aparecen con el giro, antes que los carros)
  const pR=A.p(kFun-0.15,0.5,'softLand');
  const hiR=t>kRie-0.05?Math.max(0,1-(t-kRie)/0.9):0;
  if(pR>0){
    [[OB,0.6],[0,1]].forEach(([o,al])=>{
      A.line([P(pt(-L,o)),P(pt(L+10,o))],{stroke:hiR>0?ACC:'#fff',lw:6+hiR*3,alpha:al,progress:pR,glow:hiR*25});
      for(let s=-L;s<L;s+=44){
        const f=(s+L)/(2*L); if(f>pR) break;
        A.line([P(pt(s,o-4)),P(pt(s,o-16))],{stroke:'#BFD8FF',lw:4,alpha:al*0.8});
      }
    });
  }

  // ---- polea
  const rotW=t*0.6+m*MOV/Rw;
  A.circle(Wc.x,Wc.y,Rw,{stroke:'#fff',lw:6,fill:'#0B1A2E'});
  for(let i=0;i<3;i++){const a=rotW+i*Math.PI*2/3; A.line([[Wc.x,Wc.y],[Wc.x+Math.cos(a)*Rw,Wc.y+Math.sin(a)*Rw]],{stroke:'#fff',lw:3});}
  A.circle(Wc.x,Wc.y,8,{fill:ACC});

  // ---- carro funicular
  const car=(s,o,alpha,sc,dim,num,numA,popT)=>{
    if(alpha<=0||sc<=0) return;
    const b1=pt(s-wcar/2,o), b2=pt(s+wcar/2,o);
    const hi=b1.y<b2.y?b1:b2, lo=b1.y<b2.y?b2:b1;
    const top=hi.y-hcar;
    const poly=[[b1.x,b1.y],[b2.x,b2.y],[b2.x,top],[b1.x,top]];
    const cx=(b1.x+b2.x)/2, cy=lo.y; // escala desde la base: siempre apoyado
    A.with(()=>{
      ctx.beginPath(); poly.forEach((q,i)=>i?ctx.lineTo(q[0],q[1]):ctx.moveTo(q[0],q[1])); ctx.closePath();
      ctx.fillStyle=dim?'#B8532C':ACC; ctx.fill();
      try{A.lib.hatch(ctx,[[b1.x,b1.y],[b2.x,b2.y],[b2.x,hi.y-26],[b1.x,hi.y-26]],{angle:Math.PI/4,spacing:12,width:2,color:'rgba(11,20,36,0.35)'});}catch(e){}
      A.line([...poly,poly[0]],{stroke:'#fff',lw:5});
      const x0=Math.min(b1.x,b2.x)+14, span=Math.abs(b2.x-b1.x)-28;
      for(let j=0;j<3;j++) A.rect(x0+j*span/3+4,top+18,span/3-8,46,{r:6,fill:PALE});
      A.rect(Math.min(b1.x,b2.x)-6,top-12,Math.abs(b2.x-b1.x)+12,14,{r:4,fill:'#fff'});
      if(numA>0) A.label(num,cx,top-50,{size:40,bg:'#fff',color:INK,scale:A.pop(popT),alpha:numA});
    },{x:cx,y:cy,scale:sc,alpha});
  };

  // carro 2 (riel de atrás), aparece ya sobre su riel
  const p2=A.pop(kDos+0.05,0.5);
  car(sB,OB,A.clamp(p2*3),p2,true,'2',A.p(kCar+0.12,0.3)*(1-A.p(kUni,0.3)),kCar+0.12);

  // ---- UN SOLO cable: carro 1 -> polea -> carro 2
  const pc=A.p(kUni,0.9,'cruise');
  if(pc>0){
    const pts=[P(pt(sA+wcar/2+2,12)),P(pt(sW,12))];
    for(let i=1;i<=18;i++){
      const ph=Math.PI*i/18;
      const q=pt(sW+Rw*Math.sin(ph),oW-Rw*Math.cos(ph));
      pts.push(P(q));
    }
    pts.push(P(pt(sB+wcar/2+2,OB+12)));
    const lit=t>kCab-0.45;
    const pulse=lit?0.5+0.5*Math.sin((t-kCab)*14):0;
    A.line(pts,{stroke:ACC,lw:9+pulse*3,progress:pc,glow:lit?30:12});
    A.line(pts,{stroke:'#fff',lw:2.5,progress:pc,alpha:0.85});
    if(t>kCab) A.rings(Wc.x,Wc.y,kCab,{count:3,speed:420,gap:0.15,maxR:220,color:ACC,lw:5});
  }

  // carro 1 (frente) – nace de la cabina del ascensor
  car(sA,0,pM,A.lerp(0.7,1,pM),false,'1',A.p(kCar,0.3)*(1-A.p(kUni,0.3)),kCar);

  // ---- flechas de sentido opuesto
  const pa2=A.p(kCab-0.45,0.35,'softLand');
  if(pa2>0){
    const a1=pt(sA-70,-50), a2=pt(sA+70,-50);
    A.arrow(a1.x,a1.y,a2.x,a2.y,{progress:pa2,color:'#fff',lw:7,head:22});
    const c1=pt(sB+70,OB), c2=pt(sB-70,OB);
    A.arrow(c1.x,c1.y-190,c2.x,c2.y-190,{progress:pa2,color:'#fff',lw:7,head:22});
  }

  // ---- fase ascensor de edificio
  if(pM<1){
    const sE=A.lerp(-40+100*Math.sin(t*2.4),sA,pM);
    const q=pt(sE,0);
    const al=1-A.clamp(pM*1.6);
    A.line([[q.x,q.y-92],[Wc.x,Wc.y+Rw]],{stroke:'#fff',lw:4,alpha:al});
    A.with(()=>{
      A.rect(q.x-70,q.y-90,140,180,{r:10,fill:ACC,stroke:'#fff',lw:5});
      A.line([[q.x,q.y-70],[q.x,q.y+85]],{stroke:INK,lw:4});
      A.rect(q.x-50,q.y-75,100,30,{r:4,fill:PALE});
    },{x:q.x,y:q.y,alpha:al});
    // X roja: "No son ascensores de edificio"
    const tX=kAsc+0.1;
    const pX=A.p(tX,0.3,'crashIn');
    if(pX>0){
      const xa=1-A.p(kFun-0.35,0.3,'accelExit');
      A.line([[340,560],[740,1060]],{stroke:'#FF3B3B',lw:16,progress:pX,alpha:xa,glow:15});
      A.line([[740,560],[340,1060]],{stroke:'#FF3B3B',lw:16,progress:A.p(tX+0.15,0.3,'crashIn'),alpha:xa,glow:15});
    }
  }
},{x:540,y:850,scale:1,shake});

if(t>kAsc+0.1&&t<kAsc+0.5) A.flash(kAsc+0.1,0.25,0.15);
if(t>kFun-0.3&&t<kFun+0.1) A.flash(kFun-0.3,0.35,0.25);
if(t>kCab-0.02) A.flash(kCab,0.3,0.3);

// ---- rótulo inferior: una palabra a la vez, sale completa antes de que entre la siguiente
const caps=[[0.3,'EDIFICIO'],[kFun,'FUNICULAR'],[kCar,'2 CARROS'],[kRie,'RIELES'],[kPen,'PENDIENTE'],[kCab-0.1,'1 CABLE']];
for(let i=0;i<caps.length;i++){
  const st=caps[i][0], nx=i<caps.length-1?caps[i+1][0]:1e9;
  if(t<st||t>=nx) continue;
  const ain=A.p(st,0.3,'snapSettle');
  const aout=i<caps.length-1?A.p(nx-0.25,0.25,'accelExit'):0;
  const al=ain*(1-aout);
  if(al<=0.001) continue;
  const last=i===caps.length-1;
  const y=1500+(1-ain)*40-aout*50;
  A.with(()=>{
    A.text(caps[i][1],540,y,{size:last?130:110,color:last?ACC:'#fff',weight:900,align:'center'});
  },{x:540,y:y,alpha:al,scale:last?A.pop(st,0.5):A.lerp(0.9,1,ain)});
  if(i===0){
    const ps=A.p(kEd,0.35,'crashIn');
    if(ps>0) A.line([[290,1465],[290+500*ps,1465]],{stroke:'#FF3B3B',lw:12,alpha:al});
  }
  const bw=A.lerp(0,260,A.p(st,0.5,'softLand'));
  A.rect(540-bw/2,1580,bw,10,{r:5,fill:ACC,alpha:al});
}

const ac = A.accent, Y = '#FFD54F', WH = '#F4F8FF';
A.bg('#0b1a2e', '#050d18');
const C = {x: 880, y: 545}, u = {x: 0.797, y: -0.604}, n = {x: 0.604, y: 0.797}, R = 55;
const P = (s, side, off = 0) => ({x: C.x - s*u.x + (side*R + off)*n.x, y: C.y - s*u.y + (side*R + off)*n.y});
const ANG = Math.atan2(u.y, u.x);

// tiempos
const tCable = A.k('cable', 0.667), tGran = A.k('gran', 2.0), tRueda = A.k('rueda', 2.333);
const tCarro = A.k('carro', 3.333), tSube = A.k('sube', 3.667), tBaja = A.k('baja', 4.667);

// movimiento de los carros
const mv = A.p(tCarro + 0.05, 1.8, 'softInOut');
const sA = A.lerp(700, 170, mv), sB = 870 - sA;
const wheelAng = (700 - sA) / R;

// cerro
const hp = A.p(0, 0.7, 'softLand');
const Q = s => P(s, 1, 30);
const q1 = Q(20), q2 = Q(900);
const hill = [[q1.x, q1.y], [q2.x, q2.y], [q2.x - 60, 1140], [1020, 1140], [1020, q1.y]];
A.with(() => {
  ctx.beginPath(); hill.forEach((p, i) => i ? ctx.lineTo(p[0], p[1]) : ctx.moveTo(p[0], p[1])); ctx.closePath();
  ctx.fillStyle = 'rgba(77,208,225,0.07)'; ctx.fill();
  A.lib.hatch(ctx, hill, {angle: -0.6, spacing: 16, width: 1.4, color: 'rgba(160,210,240,0.25)'});
