A.bg('#0b1a33', '#050c1a', true);
const acc = A.accent;
const kS = A.k('Síguenos', 0), kCh = A.k('Chile', 1.667), kMu = A.k('mundo.', 2.667);
const kCu = A.k('¿Cuál', 3.0), kFav = A.k('favorito?', 4.333), kAsc = A.k('ascensor', 4.0);

// --- Cerro en corte ---
const hillIn = A.p(0, 0.6, 'softLand');
const hill = [[0,1130],[140,1100],[300,980],[520,820],[720,640],[880,520],[1080,500],[1080,1130]];
const shake = t > kFav ? 10 * Math.max(0, 1 - (t - kFav) / 0.35) : 0;
A.with(() => {
  A.lib.inkPath(ctx, hill, {width: 4, color: A.pal.lineWhite, closed: true, fill: 'rgba(30,60,110,0.55)', draw: hillIn});
  A.lib.hatch(ctx, hill, {angle: 0.8, spacing: 18, width: 1.5, color: 'rgba(170,200,255,0.25)'});
  // casitas del cerro
  const houses = [[160,1060,'#e85d75'],[620,700,'#4fc3f7'],[960,470,'#e85d75'],[1010,470,'#4fc3f7']];
  houses.forEach(([hx,hy,c],i)=>{
    const s = A.pop(0.15 + i*0.08);
    A.with(()=>{ A.rect(hx-28,hy-50,56,50,{fill:c,stroke:'#fff',lw:3}); A.rect(hx-8,hy-34,16,18,{fill:'#0b1a33'}); },{x:hx,y:hy,scale:s});
  });

  // --- Riel ---
  const x0=230,y0=1040,x1=850,y1=560;
  const ang = Math.atan2(y1-y0, x1-x0);
  A.line([[x0,y0],[x1,y1]], {stroke:'#fff', lw:6, progress: A.p(0.1,0.7,'glide')});
  A.line([[x0+12,y0+14],[x1+12,y1+14]], {stroke:'rgba(255,255,255,0.4)', lw:3, progress: A.p(0.15,0.7,'glide')});

  // --- Rueda / polea ---
  const px=900, py=520, pr=46;
  const ps = A.pop(0.4);
  A.with(()=>{
    A.circle(px,py,pr,{stroke:'#fff',lw:6,fill:'#13284d'});
    for(let i=0;i<4;i++){const a=t*3+i*Math.PI/2; A.line([[px,py],[px+Math.cos(a)*pr,py+Math.sin(a)*pr]],{stroke:acc,lw:4});}
    A.circle(px,py,8,{fill:acc});
  },{x:px,y:py,scale:ps});

  // --- Carros en contrapeso ---
  const u = 0.5 + 0.38*Math.sin(t*1.3 - 0.6);
  const cars = [u, 1-u];
  const carIn = A.p(0.3,0.6,'snapSettle');
  cars.forEach((uu,i)=>{
    const cx = A.lerp(x0,x1,0.08+uu*0.78), cy = A.lerp(y0,y1,0.08+uu*0.78);
    const off = i===0 ? -1 : 1; // uno sobre otro (vía doble en perspectiva)
    const ox = cx + off*14*Math.sin(ang)*-1, oy = cy - 40 + off*0;
    // cable hacia la polea
    A.line([[cx, cy-30],[px, py + (i===0?-pr:pr)*0.0]], {stroke: acc, lw:3, alpha:0.8*carIn});
    A.with(()=>{
      A.rect(-70,-80,140,80,{r:10,fill: i===0?acc:'#ffb000',stroke:'#fff',lw:4});
      A.rect(-55,-66,40,30,{r:4,fill:'#0b1a33'});
      A.rect(15,-66,40,30,{r:4,fill:'#0b1a33'});
      A.circle(-40,6,12,{fill:'#fff'}); A.circle(40,6,12,{fill:'#fff'});
    },{x:cx,y:cy-12,rot:0,alpha:carIn,scale:carIn});
    // flecha de movimiento
    const dir = i===0 ? Math.cos(t*1.3-0.6) : -Math.cos(t*1.3-0.6);
    const ax = Math.cos(ang)*Math.sign(dir)*70, ay = Math.sin(ang)*Math.sign(dir)*70;
    A.arrow(cx+ax*0.6, cy-120+ay*0.6, cx+ax*1.4, cy-120+ay*1.4, {color:'#fff', lw:5, alpha: carIn*Math.min(1,Math.abs(dir)*2)});
  });

  // --- Etiquetas CHILE / MUNDO ---
  const chA = A.clamp(1 - A.p(kCu-0.1,0.3,'accelExit'));
  if (t > kCh) { A.label('CHILE', 300, 700, {size:64, bg:acc, color:'#0b1a33', scale:A.pop(kCh), alpha:chA}); }
  if (t > kMu) {
    A.rings(330, 860, kMu, {count:3, color:acc, maxR:160, lw:4, alpha:chA});
    A.label('Y EL MUNDO', 330, 860, {size:56, bg:'#fff', color:'#0b1a33', scale:A.pop(kMu), alpha:chA});
  }

  // --- Gran "?" sobre el carro de arriba ---
  if (t > kFav - 0.05) {
    const qs = A.pop(kFav - 0.05, 0.5);
    A.with(()=>{ A.text('?', 0, 0, {size:300, color:acc, weight:'900', align:'center', stroke:'#0b1a33', strokeWidth:12}); },
      {x:420, y:620, scale:qs, rot: 0.15*Math.sin(t*6)});
  }
}, {shake});

// --- Zona secundaria: botón Seguir y luego nombres ---
const fOut = A.clamp(1 - A.p(kCu-0.15, 0.35, 'accelExit'));
if (fOut > 0.01) A.with(()=> A.follow(540, 1520, kS+0.1, kS+1.3), {alpha:fOut, x:540, y:1520, scale: A.lerp(0.85,1,fOut)});

if (t > kCu) {
  const names = ['CONCEPCIÓN','REINA VICTORIA','EL PERAL','ARTILLERÍA','POLANCO'];
  const step = 0.32;
  const idx = Math.min(names.length-1, Math.floor((t - kCu)/step));
  const local = (t - kCu) - idx*step;
  const s = A.pop(kCu + idx*step, 0.3);
  const inA = A.p(kCu,0.3,'softLand');
  A.text('¿TU FAVORITO?', 540, 1420, {size:46, color:'#fff', weight:'800', align:'center', alpha:inA});
  A.label(names[idx], 540, 1560, {size:72, bg:acc, color:'#0b1a33', scale:s});
  // puntos de progreso no numéricos: pequeños carritos
  for (let i=0;i<names.length;i++) A.circle(460+i*40, 1660, 8, {fill: i<=idx?acc:'rgba(255,255,255,0.25)'});
}
if (t > kFav) A.flash(kFav, 0.25, 0.35);
